package demo; import java.util.*; import java.io.*;
public class Probe { static String esc(String s){return s.replace("\\","\\\\").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t").replace("\f","\\f");} static String read(String n,boolean r)throws Exception{Properties p=new Properties();try(InputStream in=Probe.class.getResourceAsStream("/"+n)){if(r)p.load(new InputStreamReader(in));else p.load(in);}StringBuilder b=new StringBuilder();for(String k:new TreeSet<>(p.stringPropertyNames()))b.append(esc(k)).append('=').append(esc(p.getProperty(k))).append(';');return b.toString();} static String counted(){try{Properties p=new Properties();p.load(new ByteArrayInputStream("x=y".getBytes("ISO-8859-1")));return "counted:"+p.getProperty("x");}catch(Exception e){return e.getClass().getName()+":"+e.getMessage();}} public static String rows(){StringBuilder b=new StringBuilder();for(int i=0;i<8;i++){String n="p"+i+".properties";try{b.append(i).append('R').append('=').append(read(n,true)).append('|').append(i).append('I').append('=').append(read(n,false)).append('\n');}catch(Exception e){b.append(i).append('=').append(e.getClass().getName()).append(':').append(e.getMessage()).append('\n');}}b.append("counted=").append(counted()).append('\n');return b.toString();}public static void main(String[]x){System.out.print(rows());}}
